contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description) public {
        address admin = address(this);
        c.isAdmin(admin);
        c.newEmergencyOracle(description);
        assert(true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description) public {
        address admin = address(this);
        require(!c.isAdmin(admin), "admin must not already be set");
        c.newEmergencyOracle(description);
        assert(true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description) public {
        address caller = address(this);
        bool wasAdmin = c.isAdmin(caller);

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == !wasAdmin);
        assert(c.isAdmin(caller) == wasAdmin);
    }

    receive() external payable {}
}
